    @jakarta.annotation.PostConstruct void acquireWorkerLock()throws Exception{if(!enabled)return;Path lock=runtime.directory("worker").resolve("worker.lock");Files.createDirectories(lock.getParent());lockChannel=java.nio.channels.FileChannel.open(lock,StandardOpenOption.CREATE,StandardOpenOption.WRITE);workerLock=lockChannel.tryLock();if(workerLock==null)throw new IllegalStateException("已有部署执行器使用此工作目录");}
