    @Scheduled(fixedDelay=3000) void heartbeat(){if(enabled)jdbc.update("INSERT INTO hosting_worker_state(id,heartbeat_at) VALUES('local',?) ON DUPLICATE KEY UPDATE heartbeat_at=VALUES(heartbeat_at)",LocalDateTime.now());}
    @Scheduled(fixedDelay=2000,initialDelay=5000) public void tick(){if(!enabled||!busy.compareAndSet(false,true))return;executor.submit(()->{try{if(deletion.processNext())return;if(!Boolean.TRUE.equals(runtime.environment().get("ready"))){recovered=false;return;}if(!recovered){recover();recovered=true;}expire();var imports=jdbc.queryForList("SELECT * FROM hosted_source_jobs WHERE status='QUEUED' ORDER BY created_at LIMIT 1");if(!imports.isEmpty()){importRepository(imports.getFirst());return;}var queue=jdbc.queryForList("SELECT id FROM hosted_deployments WHERE status='QUEUED' ORDER BY created_at LIMIT 1");if(!queue.isEmpty())execute((String)queue.getFirst().get("id"));}catch(Exception e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("部署执行器本轮失败：{}",e.getClass().getSimpleName());}finally{SecurityContextHolder.clearContext();busy.set(false);}});}
