            sites.event(id,"RUNNING","新版本健康检查通过，网站访问入口已切换。数据库保留原数据。" );String old=(String)d.get("base_deployment_id");if(old!=null){runtime.stop(old);jdbc.update("UPDATE hosted_deployments SET status='STOPPED',published=FALSE,updated_at=? WHERE id=?",LocalDateTime.now(),old);}
            if("TEST".equals(candidate.get("environment_kind"))){sites.stop((String)candidate.get("id"));Object baseline=candidate.get("base_deployment_id");if(baseline!=null&&"TEST".equals(sites.rawDeployment(baseline.toString()).get("environment_kind")))sites.stop(baseline.toString());sites.event(id,"RUNNING","发布完成，已停止对应测试环境；源码、数据库副本和检测证据保留");}return;
